mapper.select:
select version_id, subject_id, school_stage, version_name, order_num, status
from edu_qb_textbook_version
where status = '0'

    and subject_id = #{subjectId}


    and school_stage = #{schoolStage}

order by order_num, version_id

select version_id, subject_id, school_stage, version_name, order_num, status
from edu_qb_textbook_version

    and subject_id = #{subjectId}
    and school_stage = #{schoolStage}

order by order_num, version_id

select version_id, subject_id, school_stage, version_name, order_num, status
from edu_qb_textbook_version
where version_id = #{versionId}

select textbook_id, version_id, textbook_name, order_num, status
from edu_qb_textbook
where textbook_id = #{textbookId}

mapper.update:
update edu_qb_textbook
set version_id = #{versionId},
    textbook_name = #{textbookName},
    order_num = #{orderNum},
    status = #{status}
where textbook_id = #{textbookId}

mapper.select:
select chapter_id, textbook_id, parent_id, chapter_name, order_num, 0 as question_count
from edu_qb_chapter
where chapter_id = #{chapterId}

mapper.update:
update edu_qb_chapter
set textbook_id = #{textbookId},
    parent_id = #{parentId},
    chapter_name = #{chapterName},
    order_num = #{orderNum}
where chapter_id = #{chapterId}

mapper.select:
select count(distinct q.question_id)
from edu_qb_question q
where q.del_flag = '0' and q.status = '0'
  and q.chapter_id = #{chapterId}

    and q.subject_id = #{subjectId}

with recursive chapter_tree as ( select chapter_id, chapter_name from edu_qb_chapter where chapter_id = #{chapterId} union all select c.chapter_id, c.chapter_name from edu_qb_chapter c inner join chapter_tree t on c.parent_id = t.chapter_id ) select count(distinct q.question_id) from edu_qb_question q where q.del_flag = '0' and q.status = '0'
and q.subject_id = #{subjectId}
and ( q.chapter_id in (select chapter_id from chapter_tree) or exists ( select 1 from chapter_tree ct where ( q.chapter_text = ct.chapter_name or q.chapter_text ilike (ct.chapter_name || ' > %') or q.chapter_text ilike ('% > ' || ct.chapter_name) or q.chapter_text ilike ('% > ' || ct.chapter_name || ' > %') ) ) )

select count(distinct q.question_id) from edu_qb_question q where q.del_flag = '0' and q.status = '0'
and q.subject_id = #{subjectId}
and ( q.chapter_id in (select chapter_id from edu_qb_chapter where textbook_id = #{textbookId}) or exists ( select 1 from edu_qb_chapter c where c.textbook_id = #{textbookId} and ( q.chapter_text = c.chapter_name or q.chapter_text ilike (c.chapter_name || ' > %') or q.chapter_text ilike ('% > ' || c.chapter_name) or q.chapter_text ilike ('% > ' || c.chapter_name || ' > %') ) ) )

select q.chapter_id as "chapterId", count(distinct q.question_id)::int as "questionCount" from edu_qb_question q inner join edu_qb_chapter c on c.chapter_id = q.chapter_id where q.del_flag = '0' and q.status = '0' and c.textbook_id = #{textbookId}
and q.subject_id = #{subjectId}
group by q.chapter_id
